"""Validate scalar R oracle evidence against the committed benchmark manifest."""

from __future__ import annotations

from hashlib import sha256
import json
from pathlib import Path
import sys


_METRIC_MAP = {
    "chi_square": "chi_square",
    "degrees_of_freedom": "degrees_of_freedom",
    "p_value": "p_value",
    "missing_patterns": "missing_patterns",
}
_GENERATOR_SCRIPT = "generate_naniar_reference.R"


def _sha256_file(path: Path) -> str:
    """Return the SHA-256 hex digest of a file's bytes."""
    return sha256(path.read_bytes()).hexdigest()


def _check_dataset_and_tool(reference: dict, manifest: dict) -> None:
    """Check the data identity and the R tool family of the artifact."""
    if reference["dataset_sha256"] != manifest["dataset_sha256"]:
        raise ValueError(
            "R reference dataset SHA-256 does not match benchmark manifest"
        )
    if reference["reference_tool"] != "R naniar":
        raise ValueError("R reference was not generated by the expected tool")
    if (
        not reference["source_script_sha256"]
        or reference["source_script_sha256"] == "unrecorded"
    ):
        raise ValueError("R reference is missing its source-script SHA-256")


def _check_generator_script(reference: dict, manifest: dict, script_path: Path) -> None:
    """Hash the committed generator script and compare it with both records."""
    actual = _sha256_file(script_path)
    if actual != manifest["reference_script_sha256"]:
        raise ValueError(
            "generator script SHA-256 does not match benchmark manifest: "
            f"actual={actual}, expected={manifest['reference_script_sha256']}"
        )
    if reference["source_script_sha256"] != actual:
        raise ValueError(
            "R reference source-script SHA-256 does not match the generator script"
        )


def _check_tool_versions(reference: dict, manifest: dict) -> None:
    """Compare the recorded naniar, R and platform identities with the manifest."""
    if reference.get("reference_tool_version") != manifest["reference_tool_version"]:
        raise ValueError(
            "R reference tool version "
            f"{reference.get('reference_tool_version')} does not match benchmark manifest "
            f"{manifest['reference_tool_version']}"
        )
    recorded = f"R {reference.get('r_version')} on {reference.get('platform')}"
    locked = manifest["reference_platform"]
    if locked != recorded and not locked.startswith(f"{recorded} ("):
        raise ValueError(
            f"R version and platform {recorded!r} do not match benchmark manifest"
        )


def _check_metrics(reference: dict, manifest: dict) -> None:
    """Fail when any locked scalar metric differs beyond its tolerance."""
    expected = manifest["expected_metrics"]
    tolerances = manifest["tolerances"]
    for reference_name, manifest_name in _METRIC_MAP.items():
        actual = float(reference["metrics"][reference_name])
        target = float(expected[manifest_name])
        tolerance = float(tolerances[manifest_name])
        if abs(actual - target) > tolerance:
            raise ValueError(
                f"{reference_name} differs from committed oracle: "
                f"actual={actual}, expected={target}, tolerance={tolerance}"
            )


def main(reference_path: Path, manifest_path: Path) -> None:
    """Fail when locked R evidence differs from the reviewed scalar oracle.

    The generator script is located next to the manifest and hashed at runtime.

    Parameters
    ----------
    reference_path : pathlib.Path
        JSON artifact emitted by ``generate_naniar_reference.R``.
    manifest_path : pathlib.Path
        Reviewed benchmark manifest that defines scalar oracle tolerances.

    Raises
    ------
    ValueError
        If the dataset, tool, generator-script SHA-256, tool or R version,
        platform, or a scalar metric fails the committed evidence contract.

    Examples
    --------
    >>> from pathlib import Path
    >>> # The CI workflow supplies reviewed paths for both arguments.
    >>> isinstance(Path("reference.json"), Path)
    True
    """
    reference = json.loads(reference_path.read_text(encoding="utf-8"))
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    _check_dataset_and_tool(reference, manifest)
    _check_generator_script(
        reference, manifest, manifest_path.parent / _GENERATOR_SCRIPT
    )
    _check_tool_versions(reference, manifest)
    _check_metrics(reference, manifest)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit(
            "Usage: validate_naniar_reference.py <reference.json> <manifest.json>"
        )
    main(Path(sys.argv[1]), Path(sys.argv[2]))
